    }

    public static void post(Runnable callback) {
        if (callback == null) {
            return;
        }

        sHandler.removeCallbacks(callback);
        sHandler.post(callback);
    }

    public static void removeCallbacks(Runnable... callbacks) {
        if (callbacks == null) {
